function coresNeeded(f, target) {
  // Even with infinitely many cores the speedup is capped at 1/(1-f).
  if (1 / (1 - f) <= target) return -1;
  var n = 1;
  // epsilon: 1/(0.1+0.9/9) is 5 up to rounding error
  while (1 / ((1 - f) + f / n) < target - 1e-12) n++;
  return n;
}
